import json, sys
spec = json.load(sys.stdin)
schemas = spec['components']['schemas']

# Check for \$ref usage in response schemas
ref_count = 0
inline_count = 0
for name, schema in schemas.items():
    if 'properties' in schema:
        for pname, prop in schema['properties'].items():
            if '\$ref' in prop:
                ref_count += 1
            else:
                inline_count += 1

print(f'Properties with \$ref: {ref_count}')
print(f'Properties inline: {inline_count}')

# Show what ref types exist  
ref_targets = set()
for name, schema in schemas.items():
    if 'properties' in schema:
        for pname, prop in schema['properties'].items():
            if '\$ref' in prop:
                ref_targets.add(prop['\$ref'])

print(f'\nUnique \$ref targets: {len(ref_targets)}')
for t in sorted(ref_targets)[:20]:
    target_name = t.split('/')[-1]
    if target_name in schemas:
        print(f'  {t} -> {json.dumps(schemas[target_name])}')

# Show a complex schema with nested \$ref
print('\n--- Complex schema example ---')
for name in ['CharactersCharacterIdGet', 'CharacterDetail']:
    if name in schemas:
        print(f'\n{name}:')
        print(json.dumps(schemas[name], indent=2)[:2000])
