import json, sys
spec = json.load(sys.stdin)
schemas = spec['components']['schemas']

# Find the character detail schema
for name in sorted(schemas.keys()):
    if 'character' in name.lower() and ('get' in name.lower() or 'detail' in name.lower()):
        print(f'{name}: {json.dumps(schemas[name], indent=2)[:800]}')
        print()
        break

# Check for schemas with nested objects
for name in sorted(schemas.keys()):
    s = schemas[name]
    if 'properties' in s:
        for pn, pv in s['properties'].items():
            if pv.get('type') == 'object' and 'properties' in pv:
                print(f'Nested object found: {name}.{pn}')
                break

# What are response schemas named like?
print('\nFirst 20 schema names:')
for name in sorted(schemas.keys())[:20]:
    print(f'  {name}')

# Count total schemas vs what we get from swagger
print(f'\nTotal schemas: {len(schemas)}')

# How does security look on an authed endpoint?
paths = spec['paths']
for p in sorted(paths.keys()):
    methods = paths[p]
    for m in ['get']:
        if m in methods:
            op = methods[m]
            if 'security' in op:
                print(f'\nSecurity on {m.upper()} {p}:')
                print(json.dumps(op['security'], indent=2))
                break
    else:
        continue
    break
